    MetricStat.add_member(:stat, Smithy::Schema::Shapes::ShapeRef.new(shape: Stat, location_name: 'Stat', traits: {"smithy.api#documentation" => "<p>The statistic to use for comparison to the threshold. It can be any CloudWatch statistic or extended statistic. For more information about statistics, \n         see <a href=\"https://docs.aws.amazon.com/AmazonCloudWatch/latest/monitoring/Statistics-definitions.html\">CloudWatch statistics definitions</a>.</p>", "smithy.api#required" => {}}))
    MetricStat.add_member(:unit, Smithy::Schema::Shapes::ShapeRef.new(shape: StandardUnit, location_name: 'Unit', traits: {"smithy.api#documentation" => "<p>If you omit <code>Unit</code> then all data that was collected with any unit is returned, along with the corresponding units that were specified\n         when the data was reported to CloudWatch. If you specify a unit, the operation returns only data that was collected with that unit specified.\n         If you specify a unit that does not match the data collected, the results of the operation are null. CloudWatch does not perform unit conversions.</p>"}))
