    RequestBasedServiceLevelIndicatorMetric.add_member(:total_request_count_metric, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricDataQueries, location_name: 'TotalRequestCountMetric', traits: {"smithy.api#documentation" => "<p>This structure defines the metric that is used as the \"total requests\" number for a request-based SLO. \n         The number observed for this metric is divided by the number of \"good requests\" or \"bad requests\" that is \n         observed for the metric defined in \n         <code>MonitoredRequestCountMetric</code>.</p>", "smithy.api#required" => {}}))
    RequestBasedServiceLevelIndicatorMetric.add_member(:monitored_request_count_metric, Smithy::Schema::Shapes::ShapeRef.new(shape: MonitoredRequestCountMetricDataQueries, location_name: 'MonitoredRequestCountMetric', traits: {"smithy.api#documentation" => "<p>This structure defines the metric that is used as the \"good request\" or \"bad request\"\n         value for a request-based SLO. \n         This value observed for the metric defined in  \n         <code>TotalRequestCountMetric</code> is divided by the number found for \n         <code>MonitoredRequestCountMetric</code> to determine the percentage of successful requests that \n         this SLO tracks.</p>", "smithy.api#required" => {}}))
    RequestBasedServiceLevelIndicatorMetric.add_member(:dependency_config, Smithy::Schema::Shapes::ShapeRef.new(shape: DependencyConfig, location_name: 'DependencyConfig', traits: {"smithy.api#documentation" => "<p>Identifies the dependency using the <code>DependencyKeyAttributes</code> and <code>DependencyOperationName</code>. </p>"}))
    RequestBasedServiceLevelIndicatorMetric.type = Types::RequestBasedServiceLevelIndicatorMetric
    RequestBasedServiceLevelIndicatorMetricConfig.add_member(:key_attributes, Smithy::Schema::Shapes::ShapeRef.new(shape: Attributes, location_name: 'KeyAttributes', traits: {"smithy.api#documentation" => "<p>If this SLO is related to a metric collected by Application Signals, you must use this field to specify which service \n         the SLO metric is related to. To do so, you must specify at least the <code>Type</code>, \n         <code>Name</code>, and <code>Environment</code> attributes.</p>\n         <p>This is a string-to-string map. It can \n         include the following fields.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>Type</code> designates the type of object this is.</p>\n            </li>\n            <li>\n               <p>\n                  <code>ResourceType</code> specifies the type of the resource. This field is used only\n            when the value of the <code>Type</code> field is <code>Resource</code> or <code>AWS::Resource</code>.</p>\n            </li>\n            <li>\n               <p>\n                  <code>Name</code> specifies the name of the object. This is used only if the value of the <code>Type</code> field\n            is <code>Service</code>, <code>RemoteService</code>, or <code>AWS::Service</code>.</p>\n            </li>\n            <li>\n               <p>\n                  <code>Identifier</code> identifies the resource objects of this resource. \n            This is used only if the value of the <code>Type</code> field\n            is <code>Resource</code> or <code>AWS::Resource</code>.</p>\n            </li>\n            <li>\n               <p>\n                  <code>Environment</code> specifies the location where this object is hosted, or what it belongs to.</p>\n            </li>\n         </ul>"}))
    RequestBasedServiceLevelIndicatorMetricConfig.add_member(:operation_name, Smithy::Schema::Shapes::ShapeRef.new(shape: OperationName, location_name: 'OperationName', traits: {"smithy.api#documentation" => "<p>If the SLO is to monitor a specific operation of the service, use this field to specify the name of that operation.</p>"}))
