    RequestBasedServiceLevelIndicatorMetricConfig.add_member(:total_request_count_metric, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricDataQueries, location_name: 'TotalRequestCountMetric', traits: {"smithy.api#documentation" => "<p>Use this structure to define the metric that you want to use as the \"total requests\" number for a request-based SLO. \n      This result will be divided by the \"good request\" or \"bad request\" value defined in  \n      <code>MonitoredRequestCountMetric</code>.</p>"}))
