    ServiceLevelIndicatorMetricConfig.add_member(:statistic, Smithy::Schema::Shapes::ShapeRef.new(shape: ServiceLevelIndicatorStatistic, location_name: 'Statistic', traits: {"smithy.api#documentation" => "<p>The statistic to use for comparison to the threshold. It can be any CloudWatch statistic or extended statistic. For more information about statistics, \n         see <a href=\"https://docs.aws.amazon.com/AmazonCloudWatch/latest/monitoring/Statistics-definitions.html\">CloudWatch statistics definitions</a>.</p>"}))
    ServiceLevelIndicatorMetricConfig.add_member(:period_seconds, Smithy::Schema::Shapes::ShapeRef.new(shape: SLIPeriodSeconds, location_name: 'PeriodSeconds', traits: {"smithy.api#documentation" => "<p>The number of seconds to use as the period for SLO evaluation. Your application's performance is compared to the \n         SLI during each period. For each period, the application is determined to have either achieved or not achieved the necessary performance.</p>"}))
    ServiceLevelIndicatorMetricConfig.add_member(:metric_data_queries, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricDataQueries, location_name: 'MetricDataQueries', traits: {"smithy.api#documentation" => "<p>If this SLO monitors a CloudWatch metric or the result of a CloudWatch metric math expression, \n     use this structure to specify that metric or expression. </p>"}))
