    ServiceLevelObjective.add_member(:description, Smithy::Schema::Shapes::ShapeRef.new(shape: ServiceLevelObjectiveDescription, location_name: 'Description', traits: {"smithy.api#documentation" => "<p>The description that you created for this SLO.</p>"}))
    ServiceLevelObjective.add_member(:created_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Timestamp, location_name: 'CreatedTime', traits: {"smithy.api#documentation" => "<p>The date and time that this SLO was created. When used in a raw HTTP Query API, it is formatted as \n         <code>yyyy-MM-dd'T'HH:mm:ss</code>. For example, \n         <code>2019-07-01T23:59:59</code>.</p>", "smithy.api#required" => {}}))
