    ServiceLevelObjective.add_member(:evaluation_type, Smithy::Schema::Shapes::ShapeRef.new(shape: EvaluationType, location_name: 'EvaluationType', traits: {"smithy.api#documentation" => "<p>Displays whether this is a period-based SLO or a request-based SLO.</p>"}))
    ServiceLevelObjective.add_member(:goal, Smithy::Schema::Shapes::ShapeRef.new(shape: Goal, location_name: 'Goal', traits: {"smithy.api#required" => {}}))
    ServiceLevelObjective.add_member(:burn_rate_configurations, Smithy::Schema::Shapes::ShapeRef.new(shape: BurnRateConfigurations, location_name: 'BurnRateConfigurations', traits: {"smithy.api#documentation" => "<p>Each object in this array defines the length of the look-back window used to calculate one burn rate metric\n         for this SLO. The burn rate measures how fast the service is consuming the error budget, relative to the attainment goal of the SLO.</p>"}))
    ServiceLevelObjective.add_member(:metric_source_type, Smithy::Schema::Shapes::ShapeRef.new(shape: MetricSourceType, location_name: 'MetricSourceType', traits: {"smithy.api#documentation" => "<p>Displays the SLI metric source type for this SLO. Supported types are:</p>\n         <ul>\n            <li>\n               <p>Service operation</p>\n            </li>\n            <li>\n               <p>Service dependency</p>\n            </li>\n            <li>\n               <p>CloudWatch metric</p>\n            </li>\n         </ul>"}))
