    ServiceLevelObjectiveBudgetReport.add_member(:arn, Smithy::Schema::Shapes::ShapeRef.new(shape: ServiceLevelObjectiveArn, location_name: 'Arn', traits: {"smithy.api#documentation" => "<p>The ARN of the SLO that this report is for.</p>", "smithy.api#required" => {}}))
    ServiceLevelObjectiveBudgetReport.add_member(:name, Smithy::Schema::Shapes::ShapeRef.new(shape: ServiceLevelObjectiveName, location_name: 'Name', traits: {"smithy.api#documentation" => "<p>The name of the SLO that this report is for.</p>", "smithy.api#required" => {}}))
    ServiceLevelObjectiveBudgetReport.add_member(:evaluation_type, Smithy::Schema::Shapes::ShapeRef.new(shape: EvaluationType, location_name: 'EvaluationType', traits: {"smithy.api#documentation" => "<p>Displays whether this budget report is for a period-based SLO or a request-based SLO.</p>"}))
    ServiceLevelObjectiveBudgetReport.add_member(:budget_status, Smithy::Schema::Shapes::ShapeRef.new(shape: ServiceLevelObjectiveBudgetStatus, location_name: 'BudgetStatus', traits: {"smithy.api#documentation" => "<p>The status of this SLO, as it relates to the error budget for the entire time interval.</p>\n         <ul>\n            <li>\n               <p>\n                  <code>OK</code> means that the SLO had remaining budget above the warning threshold,\n            as of the time that you specified in <code>TimeStamp</code>.</p>\n            </li>\n            <li>\n               <p>\n                  <code>WARNING</code> means that the SLO's remaining budget was below the warning threshold,\n            as of the time that you specified in <code>TimeStamp</code>.</p>\n            </li>\n            <li>\n               <p>\n                  <code>BREACHED</code> means that the SLO's budget was exhausted,\n            as of the time that you specified in <code>TimeStamp</code>.</p>\n            </li>\n            <li>\n               <p>\n                  <code>INSUFFICIENT_DATA</code> means that the specified start and end times were before the\n            SLO was created, or that attainment data is missing.</p>\n            </li>\n         </ul>", "smithy.api#required" => {}}))
    ServiceLevelObjectiveBudgetReport.add_member(:attainment, Smithy::Schema::Shapes::ShapeRef.new(shape: Attainment, location_name: 'Attainment', traits: {"smithy.api#documentation" => "<p>A number between 0 and 100 that represents the success percentage of your application compared\n         to the goal set by the SLO.</p>\n         <p>If this is a period-based SLO, the number is the percentage of time periods that the service has \n         attained the SLO's attainment goal, as of the time of the request.</p>\n         <p>If this is a request-based SLO, the number is the number of successful requests divided\n         by the number of total requests, multiplied by 100, during the time range that you specified in your request.</p>"}))
    ServiceLevelObjectiveBudgetReport.add_member(:total_budget_seconds, Smithy::Schema::Shapes::ShapeRef.new(shape: TotalBudgetSeconds, location_name: 'TotalBudgetSeconds', traits: {"smithy.api#documentation" => "<p>The total number of seconds in the error budget for the interval. This field is included only \n      if the SLO is a period-based SLO.</p>"}))
    ServiceLevelObjectiveBudgetReport.add_member(:budget_seconds_remaining, Smithy::Schema::Shapes::ShapeRef.new(shape: BudgetSecondsRemaining, location_name: 'BudgetSecondsRemaining', traits: {"smithy.api#documentation" => "<p>The budget amount remaining before the SLO status becomes <code>BREACHING</code>, at the time specified in\n         the \n         <code>Timestemp</code> parameter of the request. If this value is negative, then the SLO is already in <code>BREACHING</code>\n         status.</p>\n         <p> This field is included only \n         if the SLO is a period-based SLO.</p>"}))
    ServiceLevelObjectiveBudgetReport.add_member(:total_budget_requests, Smithy::Schema::Shapes::ShapeRef.new(shape: TotalBudgetRequests, location_name: 'TotalBudgetRequests', traits: {"smithy.api#documentation" => "<p>This field is displayed only for request-based SLOs. It displays the total number of failed requests that can be tolerated during the time range between the start of the \n         interval and the time stamp supplied in the budget report request. It is based on the total number of requests that occurred,\n      and the percentage specified in the attainment goal. If the number of failed requests matches this number or is higher, then \n      this SLO is currently breaching.</p>\n         <p>This number can go up and down between reports with different time stamps, based on both how many total requests occur.</p>"}))
    ServiceLevelObjectiveBudgetReport.add_member(:budget_requests_remaining, Smithy::Schema::Shapes::ShapeRef.new(shape: BudgetRequestsRemaining, location_name: 'BudgetRequestsRemaining', traits: {"smithy.api#documentation" => "<p>This field is displayed only for request-based SLOs. It displays the number of failed requests that can be tolerated before any more successful requests occur,\n         and still have the application meet its SLO goal.</p>\n         <p>This number can go up and down between different reports, based on both how many successful requests and how many failed \n         requests occur in that time.</p>"}))
    ServiceLevelObjectiveBudgetReport.add_member(:sli, Smithy::Schema::Shapes::ShapeRef.new(shape: ServiceLevelIndicator, location_name: 'Sli', traits: {"smithy.api#documentation" => "<p>A structure that contains information about the performance metric that this SLO monitors.</p>"}))
