    ServiceLevelObjectiveSummary.add_member(:created_time, Smithy::Schema::Shapes::ShapeRef.new(shape: Smithy::Schema::Shapes::Prelude::Timestamp, location_name: 'CreatedTime', traits: {"smithy.api#documentation" => "<p>The date and time that this service level objective was created. It is expressed as the number of milliseconds since Jan 1, 1970 00:00:00 UTC.</p>"}))
    ServiceLevelObjectiveSummary.add_member(:evaluation_type, Smithy::Schema::Shapes::ShapeRef.new(shape: EvaluationType, location_name: 'EvaluationType', traits: {"smithy.api#documentation" => "<p>Displays whether this is a period-based SLO or a request-based SLO.</p>"}))
